import{at as e,it as t,n,vt as r}from"./chunks/framework.B6nQ8gjX.js";var i=JSON.parse(`{"title":"History","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. Search History","slug":"_1-search-history","link":"#_1-search-history","children":[]},{"level":2,"title":"2. Keyword History","slug":"_2-keyword-history","link":"#_2-keyword-history","children":[]},{"level":2,"title":"3. Query Associations","slug":"_3-query-associations","link":"#_3-query-associations","children":[]}],"relativePath":"user-guide/settings/history.md","filePath":"user-guide/settings/history.md","lastUpdated":1795268921000}`),a={name:`user-guide/settings/history.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to “History”">​</a></h1><p>The three tabs manage opened items, search terms, and learned query associations separately.</p><h2 id="_1-search-history" tabindex="-1">1. Search History <a class="header-anchor" href="#_1-search-history" aria-label="Permalink to “1. Search History”">​</a></h2><p>Records how often and recently each file, folder, or application was opened from search results.</p><ul><li><strong>Ranking:</strong> each open adds 1 to a score capped at 10. Scores decay with a 90-day half-life. A score of 3 qualifies for H3 and 5 for H5. Quick Search has up to 3 H5 and 10 H3 slots; inline search has 1 and 3. The Full Window has no slot cap.</li><li><strong>Scope:</strong> usage can move an item ahead of other results with the same effective match grade and priority. Quick Search&#39;s type settings can lower exact file/folder matches to the strong-match grade; see <a href="./../search-syntax.html">Search Syntax</a>.</li><li><strong>Inline groups:</strong> current-folder and global results are grouped separately. Missing paths are skipped.</li><li><strong>Management:</strong> filter by keyword, delete individual entries, clear entries with at most N uses, or clear all. Lists refresh when another window records a launch. Disabling history prevents new entries; existing entries still update their counts and recency.</li></ul><h2 id="_2-keyword-history" tabindex="-1">2. Keyword History <a class="header-anchor" href="#_2-keyword-history" aria-label="Permalink to “2. Keyword History”">​</a></h2><p>Stores the original query when you execute a result or action, or open the Full Window. Typing and dismissing Quick Search alone does not create a record.</p><ul><li>Press <strong>Alt+Up / Alt+Down</strong> to browse previous queries and <strong>Ctrl+Delete</strong> to remove the current entry.</li><li>Filter, delete, clear all, or remove keywords with at most N uses. This tab has its own recording switch. When disabled, existing keywords still accumulate uses, but new keywords are not added.</li></ul><h2 id="_3-query-associations" tabindex="-1">3. Query Associations <a class="header-anchor" href="#_3-query-associations" aria-label="Permalink to “3. Query Associations”">​</a></h2><p>Stores <strong>query → target path</strong> associations independently of general usage scores.</p><ul><li>An association becomes eligible after the same normalized query is used to open a normally found result at least <strong>3 times</strong>. An open from learned recall alone does not increase this count.</li><li>At most <strong>one</strong> association supplements a query. Low-priority targets are excluded, and association-only results follow direct matches.</li><li>Filter, delete, or clear associations without resetting path usage scores.</li></ul>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};